'use client';

import React, { useState } from 'react';
import { Hotel } from 'lucide-react';
import { useLanguage } from '../../components/LanguageContext';
import ComingSoonModal from '../../components/ui/ComingSoonModal';
import Link from 'next/link';

export default function HotelsPage() {
  const { t } = useLanguage();
  const [comingSoonOpen, setComingSoonOpen] = useState(true);

  return (
    <div className="w-full flex-1 flex flex-col p-4 md:p-8 selection:bg-rose-500/30">
      <div className="max-w-md mx-auto w-full space-y-8 pb-12 pt-10 text-center">
        
        {/* Header & Coming Soon Card */}
        <div className="max-w-md mx-auto w-full bg-card border border-subtle rounded-3xl p-8 shadow-2xl flex flex-col items-center space-y-6">
          
          <div className="p-4 bg-blue-500/10 rounded-2xl border border-blue-500/20 text-blue-500">
            <Hotel className="w-10 h-10" />
          </div>
          
          <div className="space-y-2">
            <h1 className="text-2xl font-bold tracking-tight text-main">
              {t('hotels')}
            </h1>
            <div className="inline-flex items-center gap-1.5 bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20 px-3 py-1 rounded-full text-xs font-black uppercase tracking-wider">
              {t('coming_soon')}
            </div>
            <p className="text-sm text-muted leading-relaxed pt-2">
              Stays and station-adjacent lodging bookings are currently locked. Hotel integrations will launch in a subsequent phase.
            </p>
          </div>

          <button
            onClick={() => setComingSoonOpen(true)}
            className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl transition-all shadow-md active:scale-95 touch-manipulation"
          >
            Learn More
          </button>

          <Link
            href="/"
            className="text-xs font-semibold text-muted hover:text-main transition-colors pt-2 block"
          >
            ← Go back to Train Search
          </Link>
        </div>

      </div>

      <ComingSoonModal
        isOpen={comingSoonOpen}
        onClose={() => setComingSoonOpen(false)}
        serviceName={t('hotels')}
        Icon={Hotel}
      />
    </div>
  );
}
